#!/usr/bin/env python3
"""
Checksum Verification Tool for MET Inventory Files
Verifies integrity of standardized TSV files against saved checksums
"""

import hashlib
import sys
from pathlib import Path
from datetime import datetime

def calculate_checksum(filepath, algorithm='sha256'):
    """Calculate SHA-256 checksum of a file."""
    hash_obj = hashlib.new(algorithm)
    try:
        with open(filepath, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                hash_obj.update(chunk)
        return hash_obj.hexdigest()
    except Exception as e:
        return f"ERROR: {e}"

def read_checksums(checksum_file):
    """Parse CHECKSUMS.sha256 file."""
    checksums = {}
    try:
        with open(checksum_file, 'r', encoding='utf-8') as f:
            lines = f.readlines()

        current_file = None
        for line in lines:
            line = line.strip()
            if not line or line.startswith('=') or line.startswith('-'):
                continue

            if 'SOURCE' in line:
                current_file = 'source'
            elif 'OUTPUT' in line:
                current_file = 'output'
            elif current_file and len(line) == 64:  # SHA-256 is 64 hex chars
                checksums[current_file] = line

        return checksums
    except Exception as e:
        print(f"ERROR reading checksum file: {e}")
        return {}

def verify_integrity():
    """Main verification routine."""
    print("\n" + "=" * 70)
    print("MET MUSEUM INVENTORY - CHECKSUM VERIFICATION TOOL")
    print("=" * 70)
    print(f"Started: {datetime.now().isoformat()}\n")

    # Check for required files
    required_files = {
        'CHECKSUMS.sha256': 'Checksum registry',
        'met_inventory.tsv': 'Original source file',
        'met_inventory_standardized.tsv': 'Standardized output file'
    }

    print("Checking for required files...")
    for filename, description in required_files.items():
        if Path(filename).exists():
            size = Path(filename).stat().st_size
            print(f"  ✓ {filename:40} ({size:,} bytes) - {description}")
        else:
            print(f"  ✗ {filename:40} NOT FOUND")

    print("\n" + "-" * 70)

    # Read saved checksums
    print("\nReading saved checksums from CHECKSUMS.sha256...")
    saved_checksums = read_checksums('CHECKSUMS.sha256')

    if not saved_checksums:
        print("ERROR: Could not parse checksums file")
        return 1

    # Verify source file
    print("\n" + "-" * 70)
    print("VERIFYING SOURCE FILE (met_inventory.tsv)")
    print("-" * 70)

    if not Path('met_inventory.tsv').exists():
        print("✗ Source file not found - cannot verify")
        source_ok = False
    else:
        source_checksum = calculate_checksum('met_inventory.tsv', 'sha256')
        print(f"Calculated checksum: {source_checksum}")

        if 'source' in saved_checksums:
            print(f"Saved checksum:      {saved_checksums['source']}")

            if source_checksum == saved_checksums['source']:
                print("✓ MATCH - Source file integrity verified")
                source_ok = True
            else:
                print("✗ MISMATCH - Source file has been modified or corrupted")
                source_ok = False
        else:
            print("⚠ No saved source checksum to compare against")
            source_ok = None

    # Verify output file
    print("\n" + "-" * 70)
    print("VERIFYING OUTPUT FILE (met_inventory_standardized.tsv)")
    print("-" * 70)

    if not Path('met_inventory_standardized.tsv').exists():
        print("✗ Output file not found - cannot verify")
        output_ok = False
    else:
        output_checksum = calculate_checksum('met_inventory_standardized.tsv', 'sha256')
        print(f"Calculated checksum: {output_checksum}")

        if 'output' in saved_checksums:
            print(f"Saved checksum:      {saved_checksums['output']}")

            if output_checksum == saved_checksums['output']:
                print("✓ MATCH - Output file integrity verified")
                output_ok = True
            else:
                print("✗ MISMATCH - Output file has been modified or corrupted")
                output_ok = False
        else:
            print("⚠ No saved output checksum to compare against")
            output_ok = None

    # Summary
    print("\n" + "=" * 70)
    print("VERIFICATION SUMMARY")
    print("=" * 70)

    if source_ok is True and output_ok is True:
        print("\n✓✓✓ ALL FILES VERIFIED - INTEGRITY CONFIRMED ✓✓✓\n")
        print("Both files match their saved checksums.")
        print("Files have not been corrupted or modified since standardization.")
        result = 0
    elif source_ok is False or output_ok is False:
        print("\n✗✗✗ VERIFICATION FAILED - INTEGRITY COMPROMISED ✗✗✗\n")
        if source_ok is False:
            print("- Source file checksum does not match (may be modified)")
        if output_ok is False:
            print("- Output file checksum does not match (may be modified)")
        result = 1
    else:
        print("\n⚠ VERIFICATION INCOMPLETE\n")
        print("Some checksums could not be verified (missing files or saved checksums)")
        result = 2

    print(f"Completed: {datetime.now().isoformat()}")
    print("=" * 70 + "\n")

    return result

if __name__ == '__main__':
    sys.exit(verify_integrity())
